d;font-size:15px;min-height:51px;padding:10px 12px;gap:5px;border-radius:14px}.game-cta>span{display:none}.roadmap summary{font-size:13px;min-height:48px;padding:12px}.roadmap ul{grid-template-columns:1fr 1fr;gap:7px}.roadmap li{font-size:12px;padding:10px;align-items:flex-start;flex-direction:column;gap:5px}.roadmap-content>p{font-size:13px}.shelf{padding:20px 17px;margin:20px 0;gap:18px;min-height:100px;border-radius:17px}.shelf h2{font-size:29px;white-space:nowrap}.shelf p{font-size:13px;letter-spacing:.3px;line-height:1.8}.shelf-doodle{display:none}.about{padding:17px 0 8px;gap:6px}.about h2{font-size:11px;letter-spacing:0}.about h2 span{font-size:10px}.about p{font-size:11px;letter-spacing:.3px}footer{font-size:8px;padding-bottom:12px}}
