import{createEntryShell,helpIsOpen,suspendHelpPresentation,ensurePauseHelp}from'../shared/entry-shell.mjs';
import{syncPauseButton}from'../shared/game-ui.mjs';
import{createAudioAdapter}from'./platform-audio.mjs';
import{createJavelinShare}from'./share.mjs';
import {shoeSolePoints} from './shoe-contact.mjs';
import{createPresentation,advancePresentation,captureResultFrame,resultAdvice}from'./presentation.mjs';
import{createState,press,release,step,snapshot}from'./physics.mjs';
import{createJavelin3D,javelinPose,cameraPlan}from'./render3d.mjs';
import{createAudio}from'./audio.mjs';
const $=id=>document.getElementById(id),modal=$('modal'),body=$('modalBody');let state=createState(),paused=false,last=0,acc=0,history=[],replay=null,resultShown=false;
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
let records=read('pf-javelin-records-v3',[]),settings=read('pf-sport-audio',{music:.4,effects:.45,enabled:true});const sound=createAudio(settings),audio=createAudioAdapter(sound,settings,value=>write('pf-sport-audio',value));let entry=null;const share=createJavelinShare(document,window);let recorded=false,started=false,presentation=createPresentation();
const canvas=$('world'),ctx=canvas.getContext('2d'),arena=document.querySelector('.arena');const renderer=createJavelin3D(arena,()=>{canvas.hidden=false});if(renderer)canvas.hidden=true;
function inputsClear(){for(const b of document.querySelectorAll('[data-pf-key]')){for(const id of pointerIds.values()){try{if(b.hasPointerCapture?.(id))b.releasePointerCapture(id)}catch{}}}pointerIds.clear();for(const k of ['a','s','j','k'])state.held[k]=false;document.querySelectorAll('[data-pf-key]').forEach(b=>b.classList.remove('held'));}
function setPaused(v){paused=v;inputsClear();last=performance.now();acc=0;if(v)audio.suspend();else if(!replay)audio.resume();syncPauseButton($('pause'),{paused,available:started&&(!resultShown||!!replay)});}
function pauseMenu(){if(!started||resultShown&&!replay)return;setPaused(true);if(!helpIsOpen(document)){entry?.openPause();ensurePauseHelp(document,entry?.dialog.querySelector('[data-pf-pause]'))}}
function resumeGame(event){entry?.close({restoreView:false});if(event?.isTrusted)audio.unlock();setPaused(false);canvas.focus({preventScroll:true});}
function close(){modal.close();if(!started){entry?.open();return}if(started&&!resultShown){pauseMenu()}else{setPaused(false);canvas.focus({preventScroll:true})}}
function open(html){modal.removeAttribute('aria-labelledby');entry?.close({restoreView:false});modal.classList.remove('has-result');setPaused(true);body.innerHTML=html;if(!modal.open)modal.showModal()}
function fresh(){entry?.close({restoreView:false});share.reset();inputsClear();last=performance.now();acc=0;started=true;$('startScreen').hidden=true;presentation=createPresentation();$('resultToast').hidden=true;modal.close();audio.reset();state=createState();paused=false;history=[];replay=null;recorded=false;resultShown=false;syncPauseButton($('pause'),{paused:false,available:true});canvas.focus({preventScroll:true});$('viewResult').hidden=true;$('replayBadge').hidden=true;$('replayBack').hidden=true;audio.resume();}
function keyDown(k){if(!started||paused||replay||state.phase==='result')return;audio.unlock();press(state,k);document.querySelector(`[data-pf-key="${k}"]`)?.classList.add('held')}
function keyUp(k){if(!paused&&!replay)release(state,k);document.querySelector(`[data-pf-key="${k}"]`)?.classList.remove('held')}
const pointerIds=new Map();
for(const b of document.querySelectorAll('[data-pf-key]')){const k=b.dataset.pfKey;let nativeHeld=false;b.addEventListener('pointerdown',e=>{e.preventDefault();pointerIds.set(k,e.pointerId);b.setPointerCapture(e.pointerId);keyDown(k)});b.addEventListener('pointerup',e=>{e.preventDefault();pointerIds.delete(k);keyUp(k)});b.addEventListener('pointercancel',()=>{pointerIds.delete(k);state.held[k]=false;b.classList.remove('held')});b.addEventListener('contextmenu',e=>e.preventDefault());b.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(!e.repeat){nativeHeld=true;keyDown(k)}}});b.addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();nativeHeld=false;keyUp(k)}});b.addEventListener('focusout',()=>{if(nativeHeld){nativeHeld=false;pauseMenu()}})}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['a','s','j','k'].includes(k)){if(e.target.closest?.('input,textarea,select,dialog')||entry?.active||modal.open)return;e.preventDefault();if(!e.repeat)keyDown(k)}});addEventListener('keyup',e=>{if(['a','s','j','k'].includes(e.key.toLowerCase()))keyUp(e.key.toLowerCase())});addEventListener('blur',pauseMenu);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseMenu()});addEventListener('orientationchange',pauseMenu);screen.orientation?.addEventListener?.('change',pauseMenu);addEventListener('keydown',e=>{if((e.key==='Escape'||e.key.toLowerCase()==='p')&&!e.target.closest?.('input,textarea,select')&&!entry?.active&&!modal.open){e.preventDefault();pauseMenu()}});modal.addEventListener('cancel',e=>{e.preventDefault();if(!modal.classList.contains('has-result'))close()});
$('begin').onclick=()=>{audio.unlock();fresh()};$('restart').onclick=()=>{audio.unlock();fresh()};$('pause').onclick=e=>paused?resumeGame(e):pauseMenu();
function record(){if(recorded)return;recorded=true;if(!state.foul&&state.distance>0){records.push({distance:state.distance,date:new Date().toLocaleDateString('zh-TW')});records.sort((a,b)=>b.distance-a.distance);records=records.slice(0,10);write('pf-javelin-records-v3',records)}}
$('records').onclick=()=>{open(`<span class="tag">僅儲存於這部裝置</span><h2>標槍紀錄</h2>${records.length?records.map((r,i)=>`<div class="rank">${i+1}. ${r.date}<b>${r.distance.toFixed(2)} m</b></div>`).join(''):'<p>尚無有效成績。站穩、不越線，你的第一投就能留下紀錄。</p>'}<button id="closeRecords" class="primary">返回</button>`);$('closeRecords').onclick=close};
function bindResultRetry(){
 const button=$('again');let armedKey=null;
 const retry=()=>{if(button!==$('again')||!modal.open||!modal.classList.contains('has-result')||!resultShown)return;armedKey=null;modal.classList.remove('has-result');audio.unlock();fresh()};
 button.onclick=retry;
 // Own activation through release so a held key, native synthetic click, or
 // repeat cannot spill from the result into another attempt.
 button.addEventListener('keydown',event=>{if(event.key!==' '&&event.key!=='Enter')return;event.preventDefault();if(!event.repeat&&armedKey===null)armedKey=event.key});
 button.addEventListener('keyup',event=>{if(event.key!==' '&&event.key!=='Enter')return;event.preventDefault();if(armedKey!==event.key)return;armedKey=null;retry()});
 button.addEventListener('focusout',()=>{armedKey=null});
